style.css:
@-moz-document domain("developer.apple.com") {
/* Orijinal metni gizle */
    span.team-name {
        color: transparent;
        position: relative;
    }

    /* Yeni metni ekle */
    span.team-name::before {
        content: "(Enterprise) ICOB TECHNOLOGY LLC";
        color: initial;
        position: absolute;
        left: 0;
    }
}
